-- NJ-1: Add Damon Galdo (R) who ran uncontested
UPDATE house_races SET candidate2_name = 'Damon Galdo', candidate2_party = 'R', status = 'General' WHERE state_code = 'NJ' AND district = 1;

-- NJ-2: Add Zack Mullock (D) who won primary 39.7%, update status
UPDATE house_races SET candidate1_name = 'Zack Mullock', candidate1_party = 'D', status = 'General', notes = 'Zack Mullock won D primary 39.7% (16,819 votes) vs Tim Alexander 27.6% vs Bayly Winder 22.0% vs Terri Reese 10.7%. Jeff Van Drew (R) uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 2;

-- NJ-3: Add Michael McGuire (R) who won primary 58.0%
UPDATE house_races SET candidate2_name = 'Michael McGuire', candidate2_party = 'R', status = 'General', notes = 'Michael McGuire won R primary 58.0% (14,466 votes) vs Jason Cullen 24.4% vs Justin Barbera 17.7%. Herb Conaway (D) uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 3;

-- NJ-4: Add Rachel Peace (D) who won primary 72.7%
UPDATE house_races SET candidate1_name = 'Rachel Peace', candidate1_party = 'D', status = 'General', notes = 'Rachel Peace won D primary 72.7% (20,055 votes) vs John Blake 27.4%. Christopher Smith (R) uncontested incumbent. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 4;

-- NJ-5: Add Sean Kirrane (R) who ran uncontested
UPDATE house_races SET candidate2_name = 'Sean Kirrane', candidate2_party = 'R', status = 'General' WHERE state_code = 'NJ' AND district = 5;

-- NJ-6: Add Hillary Herzig (R) who ran uncontested
UPDATE house_races SET candidate2_name = 'Hillary Herzig', candidate2_party = 'R', status = 'General', notes = 'Frank Pallone (D) won primary 66.2% (31,220 votes) vs John Hsu 26.1% vs Katie Bansil 7.6%. Hillary Herzig (R) uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 6;

-- NJ-9: Add Rosie Pino (R) who won primary 51.5%
UPDATE house_races SET candidate2_name = 'Rosie Pino', candidate2_party = 'R', status = 'General', notes = 'Rosie Pino won R primary 51.5% (6,541 votes) vs Tiffany Burress 48.5% (6,173 votes) — very close. Nelida Pou (D) uncontested incumbent. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 9;

-- NJ-10: Add Carmen Bucco (R) who ran uncontested
UPDATE house_races SET candidate2_name = 'Carmen Bucco', candidate2_party = 'R', status = 'General', notes = 'LaMonica McIver (D) won primary 84.6% (36,343 votes) vs Lawrence Poster 15.4%. Carmen Bucco (R) uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ' AND district = 10;

